import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useIntl } from 'react-intl';

const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';

/*
 * The labels are UI copy, so they are translatable messages rather than literals. `defaultMessage`
 * carries the English inline, which is what makes this work with no `translations/` entry: that
 * directory is Tier 2 (owner Integration/SI Partner) and is populated by the extraction step, so
 * a component cannot add to it. Until extraction runs, every locale renders `defaultMessage`;
 * once it does, the non-English storefronts pick up their own strings with no change here.
 *
 * The ids follow the base template's namespace for PDP labels — `product_view.label.quantity`
 * and `product_view.label.variant_type` are its siblings — so a translator finds them with the
 * rest of the PDP copy.
 *
 * Placeholder syntax `{price}` lets a locale reorder the price relative to the label
 * (e.g. German might prefer "595,00 € war" — Was after the figure).
 */
const WAS_PRICE_MESSAGE = {
  id: 'product_view.label.was_price',
  defaultMessage: 'Was {price}',
};
const NOW_PRICE_MESSAGE = {
  id: 'product_view.label.now_price',
  defaultMessage: 'Now {price}',
};

type ZimmProductPriceProps = {
  /**
   * The price the shopper pays today, already formatted by the caller (`intl.formatNumber`
   * at the page). This atom does no formatting of its own so it stays usable from Storybook
   * without an intl provider.
   * — Full price: the only price shown.
   * — On sale: rendered as the "Now" figure alongside `originalPrice`.
   *
   * Optional because the page's mapper resolves an absent price to `''` rather than to a
   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
   * unchanged and the decision not to render is taken here.
   */
  currentPrice?: string;
  /**
   * The original full price before the sale, formatted the same way as `currentPrice`.
   * When supplied the atom switches to the Was/Now sale treatment (PRC-09):
   * "Was {originalPrice} Now {currentPrice}". Absent for full-price items.
   */
  originalPrice?: string;
  /**
   * When true, renders an empty container instead of the price — used while a variant
   * re-fetch is in progress to preserve the layout slot without showing stale Was/Now values.
   */
  isLoading?: boolean;
};

/**
 * Atom — the single, full product price. All styling, type included, lives in
 * `zimmProductPrice.css.ts` and is consumed through the theme, per the
 * one-canonical-styling-surface rule. Type in particular must stay there rather than on the
 * element, or SFCC-194's `sale` variant cannot override it with a composite `textStyle` of its
 * own — see that file's docblock.
 *
 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
 */
export const ZimmProductPrice = ({ currentPrice, originalPrice, isLoading }: ZimmProductPriceProps) => {
  // During loading, always use the sale variant so the flex row + two-span structure is rendered
  // (invisible) — this preserves the exact Was/Now dimensions while the fetch is in flight.
  const variant = isLoading || originalPrice ? 'sale' : 'default';

  // Guard below the hook, never above it: an early return before `useMultiStyleConfig` makes
  // the hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather
  // than a warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
  // `intl.formatMessage`, not a destructured `{ formatMessage }`: destructuring a method off
  // `useIntl()` trips `@typescript-eslint/unbound-method`. See `zimmProductStyleCode/index.tsx`
  // for the established pattern and why `useUiCopy` is wrong here.
  const intl = useIntl();

  // Preserve the full Was/Now layout slot while a variant re-fetch is in progress.
  // opacity:0 keeps the element in the flow (height + gap retained), hides the placeholder
  // content visually, and keeps it in the accessibility tree — so AT registers the live
  // region before the price arrives and announces the update when the fetch settles.
  // visibility:hidden was not used: it removes the element from the AT, defeating the
  // live-region purpose even though aria-hidden is absent.
  if (isLoading) {
    return (
      <chakra.p __css={styles.container} opacity={0} data-testid="product-price" aria-live="polite" aria-atomic="true">
        <chakra.span __css={styles.wasPrice}> </chakra.span> <chakra.span __css={styles.nowPrice}> </chakra.span>
      </chakra.p>
    );
  }

  if (!currentPrice) return null;

  return (
    /*
     * `aria-live`/`aria-atomic` sit on the price element itself, so this atom still renders
     * exactly one node.
     *
     * WCAG 2.2 AA 4.1.3 (Status Messages) is the requirement. Choosing a variant rewrites the
     * URL's `pid` (`pages/product-detail/index.tsx` lines 379-389), which re-keys the
     * `useProduct` call on line 204 and hands this atom a different string. Focus never moves,
     * so without a live region the price is repainted silently and a screen-reader user is never
     * told the number they are buying at has changed. React mutates this element's text in
     * place, which is exactly the change a live region reports; `aria-atomic` makes it read the
     * whole price rather than only the characters that differ.
     *
     * Base `display-price/current-price.jsx` instead puts the announcement in a second, hidden
     * node (its lines 57-66). It needs one because it prefixes a `labelForA11y` product name to
     * order the name ahead of the price (its comment on line 56); this atom has no such prefix
     * to order — `currentPrice` arrives already formatted and localised by the page and there is
     * no `useIntl` here — so the extra node would carry a verbatim duplicate of the visible text.
     * That costs twice: every screen reader would read the price twice on first load, and the
     * extra child breaks `ZimmProductContent`'s `play` tests, which assert the exact child count
     * of its flex column (`WithoutDescription`, `RhythmWithDescription`, `BlankDescription`).
     */
    <chakra.p __css={styles.container} data-testid="product-price" aria-live="polite" aria-atomic="true">
      {originalPrice ? (
        <>
          {/* PRC-09 Was/Now treatment — Figma node 40001028:9179 */}
          <chakra.span __css={styles.wasPrice} data-testid="product-was-price">
            {intl.formatMessage(WAS_PRICE_MESSAGE, { price: originalPrice })}
          </chakra.span>
          {/*
            A real space so `textContent` — what a screen reader reads with aria-atomic and
            what a shopper copies — is "Was $795.00 Now $595.00" with a separator. A
            whitespace-only flex item adds no width (CSS Flexbox §4), so the recipe's `gap`
            remains the only visual spacing between the spans.
          */}{' '}
          <chakra.span __css={styles.nowPrice} data-testid="product-now-price">
            {intl.formatMessage(NOW_PRICE_MESSAGE, { price: currentPrice })}
          </chakra.span>
        </>
      ) : (
        currentPrice
      )}
    </chakra.p>
  );
};

